// Derives plan progress from ticket `**Status**` blocks. The Status block is
// the only writable record of ticket status; everything here is generated.

const TICKET_HEADING = /^### ([A-Z]+-\d+): (.+)$/;
const SECTION_HEADING = /^#{2,3} /;
const COMPLETE = /^Complete on (\d{4}-\d{2}-\d{2})\b/;

export const PLAN_START =
  "<!-- plan-progress:start: generated by `npm run plan:status` from ticket Status blocks; do not edit -->";
export const PLAN_END = "<!-- plan-progress:end -->";
export const INDEX_START =
  "<!-- plan-index:start: generated by `npm run plan:status`; do not edit -->";
export const INDEX_END = "<!-- plan-index:end -->";

/**
 * Lists every ticket in a plan with the status its own Status block records,
 * so progress is read from the tickets rather than restated by hand.
 */
export function parseTickets(markdown) {
  const lines = markdown.split("\n");
  const tickets = [];
  for (let index = 0; index < lines.length; index += 1) {
    const heading = TICKET_HEADING.exec(lines[index]);
    if (heading === null) continue;
    const [, id, title] = heading;
    tickets.push({ id, title, status: readStatus(lines, index + 1) });
  }
  return tickets;
}

/**
 * Reads the first sentence after a ticket's `**Status**` marker, stopping at
 * the next heading; a ticket without a Status block is open.
 */
function readStatus(lines, start) {
  for (let index = start; index < lines.length; index += 1) {
    if (SECTION_HEADING.test(lines[index])) break;
    if (lines[index].trim() !== "**Status**") continue;
    const text = lines.slice(index + 1).find((line) => line.trim() !== "");
    if (text === undefined) break;
    const complete = COMPLETE.exec(text.trim());
    if (complete !== null)
      return { complete: true, label: `Complete on ${complete[1]}` };
    return {
      complete: false,
      label: text.trim().split(". ")[0].replace(/\.$/, ""),
    };
  }
  return { complete: false, label: "Open" };
}

/** Summarizes ticket completion as one phrase shared by plans and the index. */
export function describeProgress(tickets) {
  const done = tickets.filter((ticket) => ticket.status.complete).length;
  return `${done} of ${tickets.length} tickets complete`;
}

/** Renders the generated progress block placed under a plan's title. */
export function renderPlanBlock(tickets) {
  const rows = tickets.map(
    (ticket) =>
      `| ${ticket.id} | ${ticket.title.replaceAll("|", "\\|")} | ${ticket.status.label} |`,
  );
  return [
    PLAN_START,
    "",
    `Progress: ${describeProgress(tickets)}.`,
    "",
    "| Ticket | Title | Status |",
    "| --- | --- | --- |",
    ...rows,
    "",
    PLAN_END,
  ].join("\n");
}

/**
 * Renders the generated plan list for `docs/implementation_plan/README.md`,
 * one heading per feature folder so equal spec numbers in different features
 * stay apart. Plans arrive sorted by feature.
 */
export function renderIndexBlock(plans) {
  const lines = [];
  for (const [index, plan] of plans.entries()) {
    if (plans[index - 1]?.feature !== plan.feature)
      lines.push(`### ${plan.feature}`, "");
    lines.push(
      `- [${plan.title}](${plan.file}) - ${describeProgress(plan.tickets)}`,
    );
    if (plans[index + 1]?.feature !== plan.feature) lines.push("");
  }
  return [INDEX_START, "", ...lines, INDEX_END].join("\n");
}

/**
 * Replaces the marked block in a document, or inserts it after the given line
 * when the document has no block yet, so new plans pick it up automatically.
 */
export function upsertBlock(markdown, start, end, block, insertAfter) {
  const from = markdown.indexOf(start);
  if (from !== -1) {
    const to = markdown.indexOf(end, from);
    if (to === -1) throw new Error(`Found "${start}" without its end marker.`);
    return markdown.slice(0, from) + block + markdown.slice(to + end.length);
  }
  const lines = markdown.split("\n");
  const at = lines.findIndex(insertAfter);
  if (at === -1)
    throw new Error("Found no place to insert the generated block.");
  lines.splice(at + 1, 0, "", block);
  return lines.join("\n");
}
